package ru.ryadom.calendar;
import android.content.Context;import org.json.*;import org.w3c.dom.*;import java.util.*;
/** Explicit writes. No attendees are added or invitations sent by mirroring. */
final class EventWrites {
 static final String TOKEN_FIELD="<t:ExtendedFieldURI DistinguishedPropertySetId=\"PublicStrings\" PropertyName=\"PekloToken\" PropertyType=\"String\"/>";
 static String envelope(String body){return "<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\" xmlns:m=\""+Providers.M+"\" xmlns:t=\""+Providers.T+"\"><s:Header><t:RequestServerVersion Version=\"Exchange2010_SP2\"/></s:Header><s:Body>"+body+"</s:Body></s:Envelope>";}
 static Document soap(JSONObject a,String body)throws Exception {Document doc=Providers.request(a,"POST",ExchangeEndpoint.normalize(a.optString("endpoint")),envelope(body),null);if(Providers.elements(doc.getDocumentElement(),Providers.M,"ResponseCode").isEmpty())throw new Providers.Failure("Сервер не подтвердил операцию.",false);for(Element code:Providers.elements(doc.getDocumentElement(),Providers.M,"ResponseCode"))if(!"NoError".equals(code.getTextContent()))throw new Providers.Failure("Exchange: "+(code.getTextContent().matches("[A-Za-z0-9]{1,80}")?code.getTextContent():"ошибка записи"),false);return doc;}
 static String tag(String name,String value){return "<t:"+name+">"+Providers.xml(value)+"</t:"+name+">";}
 static String identity(Event e){return "<t:ItemId Id=\""+Providers.xml(e.id)+"\""+(e.etag.isEmpty()?"":" ChangeKey=\""+Providers.xml(e.etag)+"\"")+"/>";}
 static String fields(Event e,String token){return tag("Subject",e.title)+"<t:Body BodyType=\"Text\">"+Providers.xml(e.description)+"</t:Body>"+tag("ReminderIsSet",""+(e.reminderMinutes>=0))+tag("ReminderMinutesBeforeStart",""+Math.max(0,e.reminderMinutes))+(token.isEmpty()?"":"<t:ExtendedProperty>"+TOKEN_FIELD+tag("Value",token)+"</t:ExtendedProperty>")+tag("Start",Providers.iso(e.start))+tag("End",Providers.iso(e.end))+tag("IsAllDayEvent",""+e.allDay)+tag("LegacyFreeBusyStatus","Busy")+tag("Location",e.location);}
 static String set(String uri,String payload){return "<t:SetItemField><t:FieldURI FieldURI=\""+uri+"\"/><t:CalendarItem>"+payload+"</t:CalendarItem></t:SetItemField>";}
 static String updateBody(Event before,Event e){String updates=set("item:Subject",tag("Subject",e.title))+set("item:Body","<t:Body BodyType=\"Text\">"+Providers.xml(e.description)+"</t:Body>")+set("item:ReminderIsSet",tag("ReminderIsSet",""+(e.reminderMinutes>=0)))+set("item:ReminderMinutesBeforeStart",tag("ReminderMinutesBeforeStart",""+Math.max(0,e.reminderMinutes)))+set("calendar:Start",tag("Start",Providers.iso(e.start)))+set("calendar:End",tag("End",Providers.iso(e.end)))+set("calendar:IsAllDayEvent",tag("IsAllDayEvent",""+e.allDay))+set("calendar:Location",tag("Location",e.location));return "<m:UpdateItem ConflictResolution=\"NeverOverwrite\" SendMeetingInvitationsOrCancellations=\"SendToNone\"><m:ItemChanges><t:ItemChange>"+identity(before)+"<t:Updates>"+updates+"</t:Updates></t:ItemChange></m:ItemChanges></m:UpdateItem>";}
 static Event findToken(JSONObject a,String token)throws Exception {Document doc=soap(a,"<m:FindItem Traversal=\"Shallow\"><m:ItemShape><t:BaseShape>IdOnly</t:BaseShape></m:ItemShape><m:Restriction><t:IsEqualTo>"+TOKEN_FIELD+"<t:FieldURIOrConstant><t:Constant Value=\""+Providers.xml(token)+"\"/></t:FieldURIOrConstant></t:IsEqualTo></m:Restriction><m:ParentFolderIds><t:DistinguishedFolderId Id=\"calendar\"/></m:ParentFolderIds></m:FindItem>");List<Element> ids=Providers.elements(doc.getDocumentElement(),Providers.T,"ItemId");if(ids.size()>1)throw new Providers.Failure("Обнаружены повторные копии: автоматическая запись остановлена.",false);if(ids.isEmpty())return null;Event e=new Event();e.id=ids.get(0).getAttribute("Id");e.etag=ids.get(0).getAttribute("ChangeKey");e.source=a.optString("id");e.calendar="main";return e;}
 static Event detail(Context c,JSONObject a,Event e)throws Exception{if(!"ews".equals(a.optString("type")))return e;Document doc=soap(a,"<m:GetItem><m:ItemShape><t:BaseShape>AllProperties</t:BaseShape><t:BodyType>Text</t:BodyType><t:AdditionalProperties>"+TOKEN_FIELD+"</t:AdditionalProperties></m:ItemShape><m:ItemIds><t:ItemId Id=\""+Providers.xml(e.id)+"\"/></m:ItemIds></m:GetItem>");List<Element> items=Providers.elements(doc.getDocumentElement(),Providers.T,"CalendarItem");if(items.isEmpty())throw new Providers.Failure("Встреча больше недоступна.",false);return Providers.ewsEvent(items.get(0),a.optString("id"));}
 static Event save(Context c,JSONObject a,String calendar,Event before,Event desired,String token)throws Exception{
  if(desired.title.trim().isEmpty()||desired.end<=desired.start||desired.reminderMinutes< -1||desired.reminderMinutes>525600)throw new Providers.Failure("Проверьте название, время и напоминание (до 525600 минут).",false);
  if("device".equals(a.optString("type")))return DeviceWrites.save(c,calendar,before,desired,token);
  if("yandex".equals(a.optString("type")))return DavWrites.save(a,calendar,before,desired,token);
  if(!"ews".equals(a.optString("type")))throw new Providers.Failure("Источник не поддерживает запись.",false);
  if(before==null)before=findToken(a,token);
  String body=before==null?"<m:CreateItem SendMeetingInvitations=\"SendToNone\"><m:SavedItemFolderId><t:DistinguishedFolderId Id=\"calendar\"/></m:SavedItemFolderId><m:Items><t:CalendarItem>"+fields(desired,token)+"</t:CalendarItem></m:Items></m:CreateItem>":updateBody(before,desired);
  Document doc=soap(a,body);List<Element> ids=Providers.elements(doc.getDocumentElement(),Providers.T,"ItemId");if(ids.isEmpty())throw new Providers.Failure("Сервер не подтвердил запись. Повторите с той же формой.",false);Event saved=Event.from(desired.json());saved.id=ids.get(0).getAttribute("Id");saved.etag=ids.get(0).getAttribute("ChangeKey");saved.calendar=calendar;saved.source=a.optString("id");saved.stableId=saved.id;return saved;
 }
 static Event recover(Context c,JSONObject a,String calendar,String token)throws Exception{
  if("ews".equals(a.optString("type")))return findToken(a,token);
  if("device".equals(a.optString("type"))){DeviceWrites.require(c);try(android.database.Cursor rows=c.getContentResolver().query(android.provider.CalendarContract.Events.CONTENT_URI,new String[]{"_id","dtstart","dtend"},"calendar_id=? AND customAppUri=? AND deleted=0",new String[]{calendar,"peklo:"+token},null)){if(rows==null)throw new Providers.Failure("Не удалось проверить запись копии.",false);if(!rows.moveToFirst())return null;Event e=new Event();e.id=rows.getString(0)+"|"+rows.getLong(1);e.stableId=rows.getString(0);e.start=rows.getLong(1);e.end=rows.getLong(2);e.calendar=calendar;e.source=a.optString("id");e.copyToken=token;return e;}}
  String url=calendar+(calendar.endsWith("/")?"":"/")+"peklo-"+token+".ics";DavWrites.Resource resource=DavWrites.request(a,"GET",url,null,null,false);if(resource.status==404)return null;java.util.List<Event> events=Providers.parseIcs(resource.body,a.optString("id"),calendar,0,Long.MAX_VALUE);if(events.size()!=1||!token.equals(events.get(0).copyToken))throw new Providers.Failure("Не удалось подтвердить принадлежность копии.",false);Event e=events.get(0);e.remoteUri=url;e.etag=resource.etag;return e;
 }
 static void delete(Context c,JSONObject a,Event e)throws Exception{if("device".equals(a.optString("type"))){DeviceWrites.delete(c,e);return;}if("yandex".equals(a.optString("type"))){DavWrites.delete(a,e);return;}if(Providers.deleted(c,a,e))return;soap(a,"<m:DeleteItem DeleteType=\"MoveToDeletedItems\" SendMeetingCancellations=\"SendToNone\" AffectedTaskOccurrences=\"SpecifiedOccurrenceOnly\"><m:ItemIds>"+identity(e)+"</m:ItemIds></m:DeleteItem>");}
}
